#!/usr/bin/env node
/**
 * Issue #307 — conservative, offline plan for historical Lambda version review.
 *
 * This consumes the READ-ONLY inventory generated by audit-erasure-lambda-invokers.mjs.
 * It deliberately contains NO AWS SDK mutation imports, credentials or network calls.
 * An unreferenced historical version is NOT proved uninvokable: identity-based IAM
 * and direct invocation routes must still be independently audited.
 */
import {readFileSync} from "node:fs";
import {pathToFileURL} from "node:url";

const POSITIVE=/^[1-9]\d*$/;
const SHA=/^[A-Za-z0-9+/]{20,}={0,2}$/;
const STATUS="BLOCKED_PENDING_INDEPENDENT_WRITER_AND_IAM_AUDIT";

export function planHistoricalVersionRetirement(inventory,codedeploy=null) {
  if(!inventory || typeof inventory!=="object" ||
    inventory.purpose!=="issue-307-read-only-qualified-lambda-inventory" ||
    inventory.status!==STATUS ||
    inventory.replayBarrierMayBeEnabled!==false ||
    inventory.executableRecoveryMayBeEnabled!==false ||
    !Array.isArray(inventory.expectedFunctions)||!inventory.expectedFunctions.length ||
    !Array.isArray(inventory.missingExpected)||inventory.missingExpected.length ||
    !Array.isArray(inventory.functions) ||
    inventory.functions.length < inventory.expectedFunctions.length)
    throw new Error("Incomplete or non-gated Lambda source inventory");

  const names=inventory.functions.map(f=>f?.name);
  if(new Set(names).size!==names.length || names.some(n=>typeof n!=="string"))
    throw new Error("Duplicated or invalid Lambda inventory function");
  if(inventory.expectedFunctions.some(n=>!names.includes(n)) ||
    new Set(inventory.expectedFunctions).size!==inventory.expectedFunctions.length)
    throw new Error("Missing or duplicated expected Lambda names");

  const deploymentReferences=new Map();
  if(codedeploy!==null) {
    if(codedeploy?.purpose!=="issue-307-read-only-codedeploy-version-references"||
      codedeploy.status!=="BLOCKED_NOT_APPROVAL_FOR_VERSION_REMOVAL"||
      codedeploy.awsMutationsPerformed!==false||codedeploy.versionRemovalApproved!==false||
      !Array.isArray(codedeploy.deployments)||
      codedeploy.deploymentCount!==codedeploy.deployments.length||
      !Array.isArray(codedeploy.deploymentGroups)||!codedeploy.deploymentGroups.length)
      throw new Error("Incomplete or non-gated CodeDeploy reference inventory");
    if((inventory.verifiedAccount&&codedeploy.verifiedAccount!==inventory.verifiedAccount)||
      (inventory.region&&codedeploy.region!==inventory.region))
      throw new Error("CodeDeploy and Lambda inventories do not share account and region");
    const deploymentIds=new Set();
    for(const deployment of codedeploy.deployments) {
      if(!Array.isArray(deployment?.targets)||!deployment.targets.length||
        typeof deployment.deploymentId!=="string"||deploymentIds.has(deployment.deploymentId)||
        !codedeploy.deploymentGroups.includes(deployment.deploymentGroup)||
        typeof deployment.status!=="string")
        throw new Error("Incomplete CodeDeploy deployment targets");
      deploymentIds.add(deployment.deploymentId);
      for(const target of deployment.targets) {
        if(typeof target?.functionName!=="string"||typeof target.currentVersion!=="string"||
          typeof target.targetVersion!=="string"||typeof target.functionAlias!=="string")
          throw new Error("Incomplete CodeDeploy version reference");
        const refs=deploymentReferences.get(target.functionName)||[];
        refs.push({deploymentId:deployment.deploymentId,alias:target.functionAlias,
          currentVersion:target.currentVersion,targetVersion:target.targetVersion});
        deploymentReferences.set(target.functionName,refs);
      }
    }
  }

  const knownFunctionNames=new Set(inventory.functions.map(f=>f?.name));
  if([...deploymentReferences.keys()].some(name=>!knownFunctionNames.has(name)))
    throw new Error("CodeDeploy references a function absent from the Lambda inventory");

  const functions=[];
  for(const f of inventory.functions) {
    if(!Array.isArray(f.versions)||!Array.isArray(f.aliases)||
      !Array.isArray(f.eventSourceMappings)||
      !f.policies||typeof f.policies!=="object"||
      !f.urls||typeof f.urls!=="object"||
      f.approvedForReplayRelease!==false)
      throw new Error("Incomplete Lambda qualifier audit: "+f.name);
    if(!Object.hasOwn(f.policies,"unqualified") ||
      !Object.hasOwn(f.urls,"unqualified"))
      throw new Error("Missing unqualified policy/URL audit: "+f.name);

    const allVersions=new Map();
    for(const v of f.versions) {
      const q=v?.qualifier;
      if(typeof q!=="string" ||
        (q!=="$LATEST"&&!POSITIVE.test(q)) ||
        allVersions.has(q) || typeof v.codeSha256!=="string" ||
        !SHA.test(v.codeSha256))
        throw new Error("Incomplete/duplicate published version metadata: "+f.name);
      allVersions.set(q,v);
      if(q!=="$LATEST"&&!Object.hasOwn(f.policies,q))
        throw new Error("Missing version resource policy evidence: "+f.name);
    }
    if(!allVersions.has("$LATEST"))
      throw new Error("Missing $LATEST version evidence: "+f.name);

    const aliasNames=new Set();
    const protectedVersions=new Map();
    function protect(version,reason) {
      if(!POSITIVE.test(version)||!allVersions.has(version))
        throw new Error("Alias/mapping references an unknown version: "+f.name);
      const reasons=protectedVersions.get(version)||new Set();
      reasons.add(reason);
      protectedVersions.set(version,reasons);
    }
    for(const ref of deploymentReferences.get(f.name)||[]) {
      for(const [label,version] of [["current",ref.currentVersion],["target",ref.targetVersion]]) {
        if(version==="$LATEST")continue;
        if(!POSITIVE.test(version))
          throw new Error("Malformed CodeDeploy version reference: "+f.name);
        protect(version,`codedeploy:${label}`);
      }
    }
    for(const a of f.aliases) {
      if(typeof a?.name!=="string"||!a.name||
        aliasNames.has(a.name)||
        !Object.hasOwn(f.policies,a.name) ||
        !Object.hasOwn(f.urls,a.name) ||
        !a.version||typeof a.version!=="string")
        throw new Error("Incomplete alias evidence: "+f.name);
      aliasNames.add(a.name);
      protect(a.version,"alias:"+a.name);
      const weights=a.additionalVersions||{};
      if(typeof weights!=="object"||Array.isArray(weights))
        throw new Error("Malformed weighted alias evidence: "+f.name);
      for(const version of Object.keys(weights)) {
        const weight=weights[version];
        if(typeof weight!=="number"||!Number.isFinite(weight)||weight<0||weight>1)
          throw new Error("Malformed weighted alias: "+f.name);
        protect(version,"weighted-alias:"+a.name);
      }
    }

    // Mappings can target an alias, a numbered version, or $LATEST. Any
    // qualifier not explained by the inventory is a hard audit failure.
    for(const mapping of f.eventSourceMappings) {
      if(typeof mapping?.qualifier!=="string" ||
        typeof mapping.state!=="string" ||
        typeof mapping.sourceService!=="string")
        throw new Error("Malformed event-source evidence: "+f.name);
      const qualifier=mapping.qualifier;
      if(qualifier==="unqualified"||qualifier==="$LATEST")continue;
      if(POSITIVE.test(qualifier))protect(qualifier,"event-source:"+mapping.state);
      else if(!aliasNames.has(qualifier))
        throw new Error("Unknown mapping qualifier: "+f.name);
      // Alias routes are already protected regardless of mapping state.
    }

    const reviewCandidates=[];
    const retained=[];
    for(const [version,v] of allVersions) {
      if(version==="$LATEST")continue;
      const policy=f.policies[version];
      if(typeof policy?.statementCount!=="number" ||
        !Number.isSafeInteger(policy.statementCount) ||
        policy.statementCount<0)
        throw new Error("Invalid version policy evidence: "+f.name);
      const reasons=[...(protectedVersions.get(version)||[])];
      if(policy.statementCount>0)reasons.push("version-resource-policy");
      if(Object.hasOwn(f.urls,version)&&f.urls[version]!==null)
        reasons.push("qualified-function-url");
      const row={version,codeSha256:v.codeSha256,
        lastModified:v.lastModified??null};
      if(reasons.length)retained.push({...row,reasons:reasons.sort()});
      else reviewCandidates.push({...row,
        designation:"UNREFERENCED_IN_LAMBDA_SNAPSHOT_ONLY",
        directInvocationAndCodeDeployUnverified:true,
        safeToDelete:false});
    }
    const sortNumeric=(a,b)=>Number(a.version)-Number(b.version);
    reviewCandidates.sort(sortNumeric);
    retained.sort(sortNumeric);
    functions.push({name:f.name,published:allVersions.size-1,
      retained,reviewCandidates,
      mappingCount:f.eventSourceMappings.length,
      codeDeployReferenceCount:(deploymentReferences.get(f.name)||[]).length,
      unknownDirectInvokers:true});
  }

  functions.sort((a,b)=>a.name.localeCompare(b.name));
  return {
    purpose:"issue-307-historical-lambda-retirement-review",
    status:"REVIEW_ONLY_NEVER_EXECUTE",
    totalPublishedVersions:functions.reduce((sum,f)=>sum+f.published,0),
    totalReviewCandidates:functions.reduce((sum,f)=>sum+f.reviewCandidates.length,0),
    functions,
    // No positive safety conclusion can be drawn from resource-policy absence.
    mustIndependentlyVerify:[
      "Identity-based IAM permissions including admin, users, roles and SSO permission sets",
      "CloudFormation/SAM references, deployments in progress and rollback requirements",
      "EventBridge, Step Functions, direct/SDK invokes, cross-account permission and legacy naming",
      "CloudTrail Lambda data events and qualified invocation metrics, including logging coverage",
      "Every account/region and every historical bundle digest against replay admission code",
      "Read-only backup and operator/security signoff before any separate version removal",
    ],
    codeDeployReferencesProvided:codedeploy!==null,
    action:"NO_LAMBDA_DELETIONS_OR_POLICY_CHANGES",
    replayBarrierMayBeEnabled:false,
    executableRecoveryMayBeEnabled:false,
  };
}

export function main(argv=process.argv.slice(2)) {
  const inventoryArgs=argv.filter(arg=>arg.startsWith("--inventory="));
  const deployArgs=argv.filter(arg=>arg.startsWith("--codedeploy="));
  if(argv.length!==inventoryArgs.length+deployArgs.length||inventoryArgs.length!==1||deployArgs.length>1)
    throw new Error("Usage: node scripts/plan-erasure-lambda-versions.mjs --inventory=<read-only-inventory.json> [--codedeploy=<read-only-target-inventory.json>]");
  const file=inventoryArgs[0].slice("--inventory=".length);
  const source=JSON.parse(readFileSync(file,"utf8"));
  const codedeploy=deployArgs.length?JSON.parse(readFileSync(deployArgs[0].slice("--codedeploy=".length),"utf8")):null;
  const report=planHistoricalVersionRetirement(source,codedeploy);
  process.stdout.write(JSON.stringify(report,null,2)+"\n");
  // Fail closed on purpose: this is never CI acceptance of recovery.
  process.exitCode=2;
}

if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href) {
  try {main();} catch(error) {
    process.stderr.write("Historical Lambda retirement audit INCOMPLETE: "+error.message+"\n");
    process.exitCode=2;
  }
}
